const charMap = {
    '　': 0x00,

    // Hiragana
    'あ': 0x01, 'い': 0x02, 'う': 0x03, 'え': 0x04, 'お': 0x05,
    'か': 0x06, 'き': 0x07, 'く': 0x08, 'け': 0x09, 'こ': 0x0A,
    'さ': 0x0B, 'し': 0x0C, 'す': 0x0D, 'せ': 0x0E, 'そ': 0x0F,
    'た': 0x10, 'ち': 0x11, 'つ': 0x12, 'て': 0x13, 'と': 0x14,
    'な': 0x15, 'に': 0x16, 'ぬ': 0x17, 'ね': 0x18, 'の': 0x19,
    'は': 0x1A, 'ひ': 0x1B, 'ふ': 0x1C, 'へ': 0x1D, 'ほ': 0x1E, 'ま': 0x1F,
    'み': 0x20, 'む': 0x21, 'め': 0x22, 'も': 0x23, 'や': 0x24, 'ゆ': 0x25, 'よ': 0x26,
    'ら': 0x27, 'り': 0x28, 'る': 0x29, 'れ': 0x2A, 'ろ': 0x2B, 'わ': 0x2C, 'を': 0x2D, 'ん': 0x2E,

    // Small Hiragana & Hiragana with Diacritics
    'ぁ': 0x2F, 'ぃ': 0x30, 'ぅ': 0x31, 'ぇ': 0x32, 'ぉ': 0x33, 'ゃ': 0x34, 'ゅ': 0x35, 'ょ': 0x36,
    'が': 0x37, 'ぎ': 0x38, 'ぐ': 0x39, 'げ': 0x3A, 'ご': 0x3B,
    'ざ': 0x3C, 'じ': 0x3D, 'ず': 0x3E, 'ぜ': 0x3F, 'ぞ': 0x40,
    'だ': 0x41, 'ぢ': 0x42, 'づ': 0x43, 'で': 0x44, 'ど': 0x45,
    'ば': 0x46, 'び': 0x47, 'ぶ': 0x48, 'べ': 0x49, 'ぼ': 0x4A,
    'ぱ': 0x4B, 'ぴ': 0x4C, 'ぷ': 0x4D, 'ぺ': 0x4E, 'ぽ': 0x4F, 'っ': 0x50,

    // Katakana
    'ア': 0x51, 'イ': 0x52, 'ウ': 0x53, 'エ': 0x54, 'オ': 0x55,
    'カ': 0x56, 'キ': 0x57, 'ク': 0x58, 'ケ': 0x59, 'コ': 0x5A,
    'サ': 0x5B, 'シ': 0x5C, 'ス': 0x5D, 'セ': 0x5E, 'ソ': 0x5F,
    'タ': 0x60, 'チ': 0x61, 'ツ': 0x62, 'テ': 0x63, 'ト': 0x64,
    'ナ': 0x65, 'ニ': 0x66, 'ヌ': 0x67, 'ネ': 0x68, 'ノ': 0x69,
    'ハ': 0x6A, 'ヒ': 0x6B, 'フ': 0x6C, 'ヘ': 0x6D, 'ホ': 0x6E, 'マ': 0x6F,
    'ミ': 0x70, 'ム': 0x71, 'メ': 0x72, 'モ': 0x73, 'ヤ': 0x74, 'ユ': 0x75, 'ヨ': 0x76,
    'ラ': 0x77, 'リ': 0x78, 'ル': 0x79, 'レ': 0x7A, 'ロ': 0x7B, 'ワ': 0x7C, 'ヲ': 0x7D, 'ン': 0x7E,

    // Small Katakana & Katakana with Diacritics
    'ァ': 0x7F, 'ィ': 0x80, 'ゥ': 0x81, 'ェ': 0x82, 'ォ': 0x83, 'ャ': 0x84, 'ュ': 0x85, 'ョ': 0x86,
    'ガ': 0x87, 'ギ': 0x88, 'グ': 0x89, 'ゲ': 0x8A, 'ゴ': 0x8B,
    'ザ': 0x8C, 'ジ': 0x8D, 'ズ': 0x8E, 'ゼ': 0x8F, 'ゾ': 0x90,
    'ダ': 0x91, 'ヂ': 0x92, 'ヅ': 0x93, 'デ': 0x94, 'ド': 0x95,
    'バ': 0x96, 'ビ': 0x97, 'ブ': 0x98, 'ベ': 0x99, 'ボ': 0x9A,
    'パ': 0x9B, 'ピ': 0x9C, 'プ': 0x9D, 'ペ': 0x9E, 'ポ': 0x9F, 'ッ': 0xA0,

    // Numbers and Symbols (Fullwidth equivalents)
    '０': 0xA1, '１': 0xA2, '２': 0xA3, '３': 0xA4, '４': 0xA5,
    '５': 0xA6, '６': 0xA7, '７': 0xA8, '８': 0xA9, '９': 0xAA,
    '！': 0xAB, '？': 0xAC, '。': 0xAD, 'ー': 0xAE, '・': 0xAF,

    // Extended Japanese Symbols
    '…': 0xB0, '『': 0xB1, '』': 0xB2, '「': 0xB3, '」': 0xB4,
    '♂': 0xB5, '♀': 0xB6, '円': 0xB7, '．': 0xB8, '×': 0xB9, '／': 0xBA,

    // English letters available on the Japanese keyboard 
    'Ａ': 0xBB, 'Ｂ': 0xBC, 'Ｃ': 0xBD, 'Ｄ': 0xBE, 'Ｅ': 0xBF, 'Ｆ': 0xC0,
    'Ｇ': 0xC1, 'Ｈ': 0xC2, 'Ｉ': 0xC3, 'Ｊ': 0xC4, 'Ｋ': 0xC5, 'Ｌ': 0xC6,
    'Ｍ': 0xC7, 'Ｎ': 0xC8, 'Ｏ': 0xC9, 'Ｐ': 0xCA, 'Ｑ': 0xCB, 'Ｒ': 0xCC,
    'Ｓ': 0xCD, 'Ｔ': 0xCE, 'Ｕ': 0xCF, 'Ｖ': 0xD0, 'Ｗ': 0xD1, 'Ｘ': 0xD2,
    'Ｙ': 0xD3, 'Ｚ': 0xD4,

    'ａ': 0xD5, 'ｂ': 0xD6, 'ｃ': 0xD7, 'ｄ': 0xD8, 'ｅ': 0xD9, 'ｆ': 0xDA,
    'ｇ': 0xDB, 'ｈ': 0xDC, 'ｉ': 0xDD, 'ｊ': 0xDE, 'ｋ': 0xDF, 'ｌ': 0xE0,
    'ｍ': 0xE1, 'ｎ': 0xE2, 'ｏ': 0xE3, 'ｐ': 0xE4, 'ｑ': 0xE5, 'ｒ': 0xE6,
    'ｓ': 0xE7, 'ｔ': 0xE8, 'ｕ': 0xE9, 'ｖ': 0xEA, 'ｗ': 0xEB, 'ｘ': 0xEC,
    'ｙ': 0xED, 'ｚ': 0xEE, '►': 0xEF, '：': 0xF0,

    // these are also printable glyphs in the Japanese Gen 3 table according to PKHeX G3_JP
    // 0xFC-0xFE text controls; 0xFF terminator
    'Ä': 0xF1, 'Ö': 0xF2, 'Ü': 0xF3, 'ä': 0xF4, 'ö': 0xF5, 'ü': 0xF6,
    '↑': 0xF7, '↓': 0xF8, '←': 0xF9, '→': 0xFA, '＋': 0xFB
};

const SECTOR_SIZE = 4096;
const TERMINATOR = 0xFF;
const TEMPLATE_SAVE_B64 = "";

// convert Base64 string into an ArrayBuffer
function base64ToArrayBuffer(base64) {
    const binaryString = window.atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes.buffer;
}

// create a reverse map to turn hex bytes back into characters
const reverseCharMap = {};
for (const [char, hex] of Object.entries(charMap)) {
    reverseCharMap[hex] = char;
}

const RAW_EMERALD_SAVE_SIZE = 0x20000;
const RTC_TRAILER_SIZE = 16;
const SECTORS_PER_SAVE_SLOT = 14;
const SAVE_SECTOR_SIGNATURE = 0x08012025;
const SAVE_FOOTER = Object.freeze({
    id: 0x0FF4,
    checksum: 0x0FF6,
    signature: 0x0FF8,
    counter: 0x0FFC
});

const EMERALD_SECTION_LENGTHS = Object.freeze([
    0x0F2C,
    0x0F80, 0x0F80, 0x0F80, 0x0F08,
    0x0F80, 0x0F80, 0x0F80, 0x0F80,
    0x0F80, 0x0F80, 0x0F80, 0x0F80, 0x07D0
]);

function validateImportSize(byteLength) {
    if (byteLength === RAW_EMERALD_SAVE_SIZE || byteLength === RAW_EMERALD_SAVE_SIZE + RTC_TRAILER_SIZE) {
        return;
    }
    if (byteLength === 0x10000) {
        throw new Error("64 KiB saves are not supported.");
    }
    throw new Error("Unknown save size: expected a 128 KiB save, optionally followed by a 16-byte RTC timestamp.");
}

function calculateSectionChecksum(dataView, offset, byteLength) {
    let sum = 0;
    for (let i = 0; i < byteLength; i += 4) {
        sum = (sum + dataView.getUint32(offset + i, true)) >>> 0;
    }
    return ((sum & 0xFFFF) + (sum >>> 16)) & 0xFFFF;
}

function readValidSaveSlot(dataView, slotIndex) {
    const start = slotIndex * SECTORS_PER_SAVE_SLOT * SECTOR_SIZE;
    const sectionOffsets = [];
    let sectionMask = 0;
    let sector0Offset = -1;
    let counter = null;

    for (let i = 0; i < SECTORS_PER_SAVE_SLOT; i++) {
        const offset = start + i * SECTOR_SIZE;
        if (dataView.getUint32(offset + SAVE_FOOTER.signature, true) !== SAVE_SECTOR_SIGNATURE) {
            return null;
        }

        // check for out-of-range or duplicate ID
        const sectionId = dataView.getUint16(offset + SAVE_FOOTER.id, true);
        if (sectionId >= SECTORS_PER_SAVE_SLOT || (sectionMask & (1 << sectionId)) !== 0) {
            return null;
        }

        const checksum = calculateSectionChecksum(dataView, offset, EMERALD_SECTION_LENGTHS[sectionId]);
        if (dataView.getUint16(offset + SAVE_FOOTER.checksum, true) !== checksum) {
            return null;
        }

        // don't treat sections from different save attempts as one save
        const sectionCounter = dataView.getUint32(offset + SAVE_FOOTER.counter, true);
        if (counter !== null && counter !== sectionCounter) {
            return null;
        }
        counter = sectionCounter;
        sectionMask |= 1 << sectionId;
        sectionOffsets[sectionId] = offset;
        if (sectionId === 0) sector0Offset = offset;
    }

    // require all 14 logical sections in the same slot
    if (sectionMask !== (1 << SECTORS_PER_SAVE_SLOT) - 1) return null;
    return { sector0Offset, counter, sectionOffsets };
}

function getActiveSector0Offset(dataView) {
    validateImportSize(dataView.byteLength);
    const first = readValidSaveSlot(dataView, 0);
    const second = readValidSaveSlot(dataView, 1);

    if (!first && !second) {
        throw new Error("No complete, valid Emerald save slot was found. The file may be corrupted or use an unsupported save format.");
    }
    if (!first) return second.sector0Offset;
    if (!second) return first.sector0Offset;

    // match Emerald handling of the adjacent rollover pair
    if (first.counter === 0xFFFFFFFF && second.counter === 0) return second.sector0Offset;
    if (second.counter === 0xFFFFFFFF && first.counter === 0) return first.sector0Offset;

    // equal counters use the first slot
    return second.counter > first.counter ? second.sector0Offset : first.sector0Offset;
}

function validateTemplateSlot(dataView, slot) {
    const block1Offset = logicalOffset =>
        slot.sectionOffsets[1 + Math.floor(logicalOffset / 0xF80)] + logicalOffset % 0xF80;
    const byte = logicalOffset => dataView.getUint8(block1Offset(logicalOffset));
    const word = logicalOffset => dataView.getUint16(block1Offset(logicalOffset), true);
    const flag = id => (byte(0x1270 + (id >>> 3)) & (1 << (id & 7))) !== 0;

    const bagKey = dataView.getUint16(slot.sector0Offset + 0xAC, true);
    const itemQuantity = (pocketOffset, count, itemId) => {
        let quantity = 0;
        for (let i = 0; i < count; i++) {
            const offset = pocketOffset + i * 4;
            if (word(offset) === itemId) quantity += word(offset + 2) ^ bagKey;
        }
        return quantity;
    };

    // GAME_CLEAR, ENABLE_SHIP_FARAWAY_ISLAND
    if (!flag(0x864) || !flag(0x8D6)) {
        throw new Error("Faraway Island ferry access is not enabled.");
    }
    // DEFEATED_MEW, CAUGHT_MEW
    if (flag(0x1C7) || flag(0x1CA)) {
        throw new Error("The Mew encounter has already been completed.");
    }
    // RECEIVED_OLD_SEA_MAP, SHOWN_OLD_SEA_MAP
    if (!flag(0x13C) || flag(0x1B0)) {
        throw new Error("The Old Sea Map event is not in its expected initial state.");
    }
    // Key Item: Old Sea Map
    if (itemQuantity(0x5D8, 30, 0x178) !== 1) {
        throw new Error("The expected Old Sea Map is missing.");
    }
    // Starting map: group 13, map 6 (ミナモシティ/Lilycove Pokemon Center 1F), x=7, y=4.
    if (byte(4) !== 13 || byte(5) !== 6 || word(0) !== 7 || word(2) !== 4) {
        throw new Error("The prepared starting location has changed.");
    }
}

function prepareTemplateSave(templateBuffer) {
    try {
        validateImportSize(templateBuffer.byteLength);
        const buffer = templateBuffer.slice(0, RAW_EMERALD_SAVE_SIZE);
        const dataView = new DataView(buffer);
        const sector0Offsets = [];
        for (let slotIndex = 0; slotIndex < 2; slotIndex++) {
            const slot = readValidSaveSlot(dataView, slotIndex);
            if (!slot) throw new Error(`Save slot ${slotIndex + 1} is incomplete or corrupt.`);
            validateTemplateSlot(dataView, slot);
            sector0Offsets.push(slot.sector0Offset);
        }
        return { buffer, sector0Offsets };
    } catch (error) {
        throw new Error("Save template failed an integrity check: " + error.message);
    }
}

function parseTrainerID(rawValue, label) {
    if (rawValue === '') return null;
    if (/[^0-9]/.test(rawValue)) {
        throw new Error(`${label} must contain decimal digits only (0 - 65535) without signs, spaces, decimals, or scientific notation.`);
    }
    const value = Number(rawValue);
    if (!Number.isInteger(value) || value > 65535) {
        throw new Error(`${label} must be between 0 and 65535.`);
    }
    return value;
}

// treat TID and SID as a pair: accept both if supplied, generate both if both are blank, show error if the fields are partially filled
function resolveTrainerIDs(rawTID, rawSID) {
    const tid = parseTrainerID(rawTID, 'TID');
    const sid = parseTrainerID(rawSID, 'SID');
    if (tid === null && sid === null) {
        return { ...generateEmeraldIDs(), generated: true };
    }
    if (tid === null || sid === null) {
        throw new Error("Enter both TID and SID, or leave both blank to generate a pair. Randomize IDs replaces both values.");
    }
    return { tid, sid, generated: false };
}

// convert standard ASCII alphanumeric characters to fullwidth characters
function toFullwidth(str) {
    return str.replace(/[A-Za-z0-9]/g, function (char) {
        return String.fromCharCode(char.charCodeAt(0) + 0xFEE0);
    });
}

const MAX_TRAINER_NAME_LENGTH = 5;
const TRAINER_NAME_FIELD_SIZE = 8;

// input aliases are separate from charMap: decoding a saved byte must always return the game's canonical glyph, not whichever alias was declared last
const TRAINER_NAME_ALIASES = Object.freeze({
    ' ': '　', '!': '！', '?': '？', '.': '．', '/': '／', ':': '：', '-': 'ー', '−': 'ー', '‥': '…', '⋯': '…'
});

function normalizeTrainerName(rawName) {
    // normalize halfwidth kana locally (applying NFKC to the entire name would expand an ellipsis into three periods and change its encoded length)
    const composed = rawName
        .replace(/[\uFF61-\uFF9F]+/gu, run => run.normalize('NFKC'))
        .normalize('NFC'); // e.g. か + combining dakuten becomes が
    return Array.from(toFullwidth(composed), char => TRAINER_NAME_ALIASES[char] ?? char).join('');
}

function validateTrainerName(rawName) {
    const name = normalizeTrainerName(rawName);
    const characters = Array.from(name);
    if (characters.length === 0 || characters.every(char => char === '　')) {
        throw new Error("Enter a trainer name with at least one non-space character.");
    }

    const unsupported = [...new Set(characters.filter(char => charMap[char] === undefined))];
    if (unsupported.length > 0) {
        const details = unsupported.map(char => {
            const code = char.codePointAt(0).toString(16).toUpperCase().padStart(4, '0');
            return `${JSON.stringify(char)} (U+${code})`;
        }).join(', ');
        throw new Error(`Unsupported trainer-name character(s): ${details}.`);
    }
    if (characters.length > MAX_TRAINER_NAME_LENGTH) {
        throw new Error(`Trainer name has ${characters.length} characters after conversion; Japanese Emerald allows ${MAX_TRAINER_NAME_LENGTH}.`);
    }
    return name;
}

function decodeTrainerName(dataView, offset) {
    // get trainer name; for non-Japanese saves, only decode unambiguous Latin letters/digits/spaces: interpreting international accented letters as Japanese bytes yields kana
    const japanese = dataView.getUint16(offset + 6, true) === 0;
    let name = "";
    for (let i = 0; i < TRAINER_NAME_FIELD_SIZE; i++) {
        const byte = dataView.getUint8(offset + i);
        if (byte === TERMINATOR) return validateTrainerName(name);

        let char;
        if (japanese) {
            char = reverseCharMap[byte];
        } else if (byte === 0) {
            char = ' ';
        } else if (byte >= 0xA1 && byte <= 0xAA) {
            char = String.fromCharCode(48 + byte - 0xA1);
        } else if (byte >= 0xBB && byte <= 0xD4) {
            char = String.fromCharCode(65 + byte - 0xBB);
        } else if (byte >= 0xD5 && byte <= 0xEE) {
            char = String.fromCharCode(97 + byte - 0xD5);
        }
        if (char === undefined) {
            const hex = byte.toString(16).toUpperCase().padStart(2, '0');
            throw new Error(`Cannot safely import trainer-name byte 0x${hex}. International imports support only Latin letters, digits, and spaces; Japanese names must use printable characters. Enter a compatible name and trainer details manually.`);
        }
        name += char;
    }
    throw new Error("The imported trainer name has no terminator. Trainer details were not changed.");
}

function encodeTrainerName(rawName) {
    const name = validateTrainerName(rawName);
    // up to 5 Japanese characters + 0xFF terminator padding + 2 0x00 alignment bytes
    const bytes = new Uint8Array(TRAINER_NAME_FIELD_SIZE);
    bytes.fill(TERMINATOR, 0, MAX_TRAINER_NAME_LENGTH + 1);
    Array.from(name).forEach((char, i) => { bytes[i] = charMap[char]; });
    return bytes;
}

// check if IME is in a composition state and block export mid-composition
let trainerNameIsComposing = false;

function updateTrainerNamePreview() {
    const input = document.getElementById('trainer-name');
    const preview = document.getElementById('trainer-name-preview');
    try {
        const name = validateTrainerName(input.value);
        preview.textContent = `Name preview: 「${name}」 (${Array.from(name).length}/${MAX_TRAINER_NAME_LENGTH})`;
        preview.className = 'help-text';
        input.setAttribute('aria-invalid', 'false');
    } catch (error) {
        const empty = input.value.length === 0;
        preview.textContent = empty ? "Enter a name to preview (maximum 5 characters)." : error.message;
        preview.className = empty ? 'help-text' : 'help-text error';
        input.setAttribute('aria-invalid', String(!empty));
    }
}

function setupTrainerNameInput() {
    const input = document.getElementById('trainer-name');
    // validate encoded characters ourselves after IME composition
    input.removeAttribute('maxlength');
    input.addEventListener('input', event => {
        if (!trainerNameIsComposing && !event.isComposing) updateTrainerNamePreview();
    });
    input.addEventListener('compositionstart', () => { trainerNameIsComposing = true; });
    input.addEventListener('compositionend', () => {
        trainerNameIsComposing = false;
        updateTrainerNamePreview();
    });
    updateTrainerNamePreview();
}

setupTrainerNameInput();

const MIN_ID_ADVANCES = 1000;
const ID_ADVANCE_COUNT = 5000;

function emeraldIDPairAt(tid, advances) {
    let seed = tid;
    for (let i = 0; i <= advances; i++) {
        seed = (Math.imul(seed, 0x41C64E6D) + 0x6073) >>> 0;
    }
    return { tid, sid: seed >>> 16 };
}

function generateEmeraldIDs() {
    const tid = Math.floor(Math.random() * 0x10000);
    const advances = MIN_ID_ADVANCES + Math.floor(Math.random() * ID_ADVANCE_COUNT);
    return emeraldIDPairAt(tid, advances);
}

function setTrainerIDs({ tid, sid }) {
    document.getElementById('tid').value = tid;
    document.getElementById('sid').value = sid;
}

function randomizeIDs() {
    setTrainerIDs(generateEmeraldIDs());
    setStatus("Randomized both trainer IDs.");
}

function setStatus(msg, isError = false) {
    const el = document.getElementById('status');
    el.textContent = msg;
    el.className = isError ? 'error' : 'success';
}

let trainerImportRequest = 0;

// file parsing
document.getElementById('user-save-file').addEventListener('change', function (event) {
    const file = event.target.files[0];
    if (!file) return;

    const request = ++trainerImportRequest;
    const clearFileInput = () => {
        if (request === trainerImportRequest) event.target.value = '';
    };

    // reject unsupported sizes before allocating memory
    try {
        validateImportSize(file.size);
    } catch (error) {
        setStatus("Failed to read save: " + error.message, true);
        clearFileInput();
        return;
    }

    const reader = new FileReader();
    reader.onload = function (e) {
        if (request !== trainerImportRequest) return;
        try {
            const dataView = new DataView(e.target.result);
            const latestSector0Offset = getActiveSector0Offset(dataView);

            const gender = dataView.getUint8(latestSector0Offset + 0x0008);
            const tid = dataView.getUint16(latestSector0Offset + 0x000A, true);
            const sid = dataView.getUint16(latestSector0Offset + 0x000C, true);

            if (gender !== 0 && gender !== 1) {
                throw new Error("The selected save contains an invalid trainer gender.");
            }

            const name = decodeTrainerName(dataView, latestSector0Offset);

            document.getElementById('trainer-name').value = name;
            if (gender === 1) {
                document.getElementById('gender-girl').checked = true;
            } else {
                document.getElementById('gender-boy').checked = true;
            }
            document.getElementById('tid').value = tid;
            document.getElementById('sid').value = sid;
            updateTrainerNamePreview(); // fire input events

            setStatus("Loaded trainer info from save!");
        } catch (error) {
            console.error(error);
            setStatus("Failed to read save: " + error.message, true);
        }
    };

    reader.onerror = function () {
        if (request === trainerImportRequest) {
            setStatus("Failed to read save: The file could not be read. Please select it again.", true);
        }
    };
    reader.onabort = function () {
        if (request === trainerImportRequest) {
            setStatus("Save import cancelled. Trainer info entries were kept.", true);
        }
    };
    // loadend runs after success, error, or abort so the same file can be retried
    reader.onloadend = clearFileInput;

    try {
        reader.readAsArrayBuffer(file);
    } catch (error) {
        setStatus("Failed to read save: " + error.message, true);
        clearFileInput();
    }
});

// validate user input, edit the template, recalc checksums, then prep and trigger the download
async function generateSave() {
    try {
        if (trainerNameIsComposing) {
            throw new Error("Finish entering the trainer name before generating the save.");
        }
        const rawName = document.getElementById('trainer-name').value;
        updateTrainerNamePreview();

        // validate before IDs or template bytes change
        const nameBytes = encodeTrainerName(rawName);

        const ids = resolveTrainerIDs(
            document.getElementById('tid').value,
            document.getElementById('sid').value
        );
        const { tid, sid } = ids;
        const gender = parseInt(document.querySelector('input[name="gender"]:checked').value);

        setStatus("Processing...");

        const { buffer, sector0Offsets } = prepareTemplateSave(base64ToArrayBuffer(TEMPLATE_SAVE_B64));
        const dataView = new DataView(buffer);

        // overwrite both slots of the save file
        for (const sectorOffset of sector0Offsets) {
            // set gender, TID, and SID
            dataView.setUint8(sectorOffset + 0x0008, gender);
            dataView.setUint16(sectorOffset + 0x000A, tid, true);
            dataView.setUint16(sectorOffset + 0x000C, sid, true);

            // write the same validated name, terminator, and padding into both slots
            for (let i = 0; i < nameBytes.length; i++) {
                dataView.setUint8(sectorOffset + i, nameBytes[i]);
            }

            // recalculate section 0 checksum
            const checksum = calculateSectionChecksum(dataView, sectorOffset, EMERALD_SECTION_LENGTHS[0]);
            dataView.setUint16(sectorOffset + SAVE_FOOTER.checksum, checksum, true);
        }

        // trigger download
        const blob = new Blob([buffer], { type: "application/octet-stream" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = "OSM_Emerald_J.sav";
        a.click();
        URL.revokeObjectURL(url);

        if (ids.generated) setTrainerIDs(ids);
        setStatus(ids.generated ? "Save generated! The generated TID and SID are shown above." : "Save generated!");

    } catch (error) {
        console.error(error);
        setStatus(error.message, true);
    }
}

(function (root) {
    'use strict';
    const NATURES = ['Hardy', 'Lonely', 'Brave', 'Adamant', 'Naughty', 'Bold', 'Docile', 'Relaxed', 'Impish', 'Lax', 'Timid', 'Hasty', 'Serious', 'Jolly', 'Naive', 'Modest', 'Mild', 'Quiet', 'Bashful', 'Rash', 'Calm', 'Gentle', 'Sassy', 'Careful', 'Quirky'];
    const HP_TYPES = ['Fighting', 'Flying', 'Poison', 'Ground', 'Rock', 'Bug', 'Ghost', 'Steel', 'Fire', 'Water', 'Grass', 'Electric', 'Psychic', 'Ice', 'Dragon', 'Dark'];
    const STATS = ['hp', 'atk', 'def', 'spa', 'spd', 'spe'];
    const MAX_ADVANCE = 0xFFFFFFFF;
    const MAX_SEARCH = 1000000;
    const MAX_RESULTS = 5000;
    const PAGE_SIZE = 100;

    // RNG: state = state * 0x41C64E6D + 0x6073, modulo 2^32; use imul so the low bits remain exact even for large seeds
    function next(seed) {
        return (Math.imul(seed, 0x41C64E6D) + 0x6073) >>> 0;
    }

    // skip ahead in RNG advances by squaring the transform
    function jump(seed, advances) {
        let multiplier = 0x41C64E6D, addend = 0x6073;
        while (advances > 0) {
            if (advances % 2) seed = (Math.imul(seed, multiplier) + addend) >>> 0;
            addend = Math.imul(addend, multiplier + 1) >>> 0;
            multiplier = Math.imul(multiplier, multiplier) >>> 0;
            advances = Math.floor(advances / 2);
        }
        return seed >>> 0;
    }

    function integertest(value, label, min, max) {
        const text = String(value).trim();
        if (!/^-?\d+$/.test(text)) throw new Error(`${label} must be an integer.`);
        const number = Number(text);
        if (!Number.isSafeInteger(number) || number < min || number > max) {
            throw new Error(`${label} must be between ${min} and ${max}.`);
        }
        return number;
    }

    function validateSearch(raw) {
        const seedText = String(raw.seed).trim();
        if (!/^(?:0x)?[0-9a-f]{1,8}$/i.test(seedText)) {
            throw new Error('Seed must contain 1-8 hexadecimal digits, optionally prefixed with 0x.');
        }
        const config = {
            seed: Number.parseInt(seedText.replace(/^0x/i, ''), 16),
            tid: integertest(raw.tid, 'TID', 0, 65535),
            sid: integertest(raw.sid, 'SID', 0, 65535),
            start: integertest(raw.start, 'Start advance', 0, MAX_ADVANCE),
            end: integertest(raw.end, 'End advance', 0, MAX_ADVANCE),
            offset: integertest(raw.offset, 'Display offset', -MAX_ADVANCE, MAX_ADVANCE),
            nature: integertest(raw.nature, 'Nature', -1, 24),
            hpType: integertest(raw.hpType, 'Hidden Power type', -1, 15),
            hpPower: integertest(raw.hpPower, 'Minimum Hidden Power power', 30, 70),
            shiny: raw.shiny,
            ivs: {}
        };
        if (config.end < config.start) throw new Error('End advance must be at least the start advance.');
        if (config.end - config.start + 1 > MAX_SEARCH) {
            throw new Error(`Search at most ${MAX_SEARCH.toLocaleString('en-US')} advances at a time.`);
        }
        if (!['any', 'shiny', 'non-shiny', 'xor-zero', 'xor-one-seven'].includes(config.shiny)) {
            throw new Error('Choose a valid shiny filter.');
        }
        for (const stat of STATS) {
            const min = integertest(raw.ivs?.[stat]?.min, `${stat.toUpperCase()} minimum IV`, 0, 31);
            const max = integertest(raw.ivs?.[stat]?.max, `${stat.toUpperCase()} maximum IV`, 0, 31);
            if (min > max) throw new Error(`${stat.toUpperCase()} minimum IV cannot exceed its maximum.`);
            config.ivs[stat] = { min, max };
        }
        return config;
    }

    function fromWords(words, advance, config) {
        const [low, high, firstIVs, secondIVs] = words;
        const pid = ((high << 16) | low) >>> 0;
        const nature = pid % 25;
        const ivs = {
            hp: firstIVs & 31, atk: (firstIVs >>> 5) & 31, def: (firstIVs >>> 10) & 31,
            spa: (secondIVs >>> 5) & 31, spd: (secondIVs >>> 10) & 31, spe: secondIVs & 31
        };
        const stats = { hp: Math.floor((200 + ivs.hp) * 30 / 100) + 40 };
        const natureOrder = ['atk', 'def', 'spe', 'spa', 'spd'];
        natureOrder.forEach((stat, index) => {
            const increased = Math.floor(nature / 5) === index;
            const decreased = nature % 5 === index;
            const modifier = increased === decreased ? 10 : increased ? 11 : 9;
            stats[stat] = Math.floor((Math.floor((200 + ivs[stat]) * 30 / 100) + 5) * modifier / 10);
        });
        const hpOrder = ['hp', 'atk', 'def', 'spe', 'spa', 'spd'];
        let typeBits = 0, powerBits = 0;
        hpOrder.forEach((stat, bit) => {
            typeBits |= (ivs[stat] & 1) << bit;
            powerBits |= ((ivs[stat] >>> 1) & 1) << bit;
        });
        const shinyXor = config.tid ^ config.sid ^ low ^ high;
        return {
            advance, displayAdvance: advance - config.offset, pid, nature, ivs, stats,
            hpType: Math.floor(typeBits * 15 / 63), hpPower: Math.floor(powerBits * 40 / 63) + 30,
            shinyXor, shiny: shinyXor < 8, ability: 'Synchronize'
        };
    }

    function matches(row, config) {
        if (config.nature !== -1 && row.nature !== config.nature) return false;
        if (config.hpType !== -1 && row.hpType !== config.hpType) return false;
        if (row.hpPower < config.hpPower) return false;
        if (config.shiny === 'shiny' && !row.shiny) return false;
        if (config.shiny === 'non-shiny' && row.shiny) return false;
        if (config.shiny === 'xor-zero' && row.shinyXor !== 0) return false;
        if (config.shiny === 'xor-one-seven' && (row.shinyXor < 1 || row.shinyXor > 7)) return false;
        return STATS.every(stat => row.ivs[stat] >= config.ivs[stat].min && row.ivs[stat] <= config.ivs[stat].max);
    }

    function createSearch(config) {
        let seed = jump(config.seed, config.start);
        const words = [];
        for (let i = 0; i < 4; i++) {
            seed = next(seed);
            words.push(seed >>> 16);
        }
        let advance = config.start, scanned = 0, done = false, truncated = false;
        const rows = [];
        return {
            rows,
            step(count = 2000) {
                for (let i = 0; i < count && !done; i++) {
                    const row = fromWords(words, advance, config);
                    if (matches(row, config)) rows.push(row);
                    scanned++;
                    advance++;
                    truncated = rows.length >= MAX_RESULTS && advance <= config.end;
                    done = advance > config.end || truncated;
                    if (!done) {
                        seed = next(seed);
                        words.shift();
                        words.push(seed >>> 16);
                    }
                }
                return { done, truncated, scanned, lastAdvance: advance - 1 };
            }
        };
    }

    const api = { NATURES, HP_TYPES, STATS, MAX_ADVANCE, MAX_SEARCH, MAX_RESULTS, PAGE_SIZE, next, jump, decimal: integertest, validateSearch, fromWords, matches, createSearch };
    if (typeof module !== 'undefined' && module.exports) module.exports = api;
    else root.MewFinder = api;
})(globalThis);

(function () {
    'use strict';

    const byId = id => document.getElementById(id);
    const tabs = [...document.querySelectorAll('[role="tab"]')];

    function activateTab(selected) {
        for (const tab of tabs) {
            const active = tab === selected;
            tab.setAttribute('aria-selected', String(active));
            tab.tabIndex = active ? 0 : -1;
            byId(tab.getAttribute('aria-controls')).hidden = !active;
        }
    }

    tabs.forEach((tab, index) => {
        tab.addEventListener('click', () => activateTab(tab));
        tab.addEventListener('keydown', event => {
            let next;
            if (event.key === 'ArrowRight') next = (index + 1) % tabs.length;
            if (event.key === 'ArrowLeft') next = (index + tabs.length - 1) % tabs.length;
            if (event.key === 'Home') next = 0;
            if (event.key === 'End') next = tabs.length - 1;
            if (next === undefined) return;
            event.preventDefault();
            activateTab(tabs[next]);
            tabs[next].focus();
        });
    });

    const helpButtons = [...document.querySelectorAll('.info-button')];

    function closeHelp(button) {
        button.setAttribute('aria-expanded', 'false');
        byId(button.getAttribute('aria-controls')).hidden = true;
    }

    helpButtons.forEach(button => {
        button.addEventListener('click', () => {
            const open = button.getAttribute('aria-expanded') !== 'true';
            helpButtons.forEach(closeHelp);
            button.setAttribute('aria-expanded', String(open));
            byId(button.getAttribute('aria-controls')).hidden = !open;
        });
    });

    document.addEventListener('keydown', event => {
        if (event.key !== 'Escape') return;
        const open = helpButtons.find(button => button.getAttribute('aria-expanded') === 'true');
        if (open) {
            closeHelp(open);
            if (!open.closest('[role="tabpanel"]').hidden) open.focus();
        }
    });

    document.addEventListener('click', event => {
        if (!event.target.closest('.info-button, .help-box')) helpButtons.forEach(closeHelp);
    });

    byId('randomize-ids').addEventListener('click', randomizeIDs);
    byId('load-save').addEventListener('click', () => byId('user-save-file').click());

    byId('save-form').addEventListener('submit', event => {
        event.preventDefault();
        generateSave();
    });

    const finder = globalThis.MewFinder;
    let current = null, results = [], page = 0;

    function status(message, error = false) {
        byId('finder-status').textContent = message;
        byId('finder-status').className = error ? 'error' : '';
    }

    function rawSearch() {
        const value = id => byId(`finder-${id}`).value;
        return {
            tid: value('tid'),
            sid: value('sid'),
            seed: value('seed'),
            start: value('start'),
            end: value('end'),
            offset: value('offset'),
            nature: value('nature'),
            hpType: value('hp-type'),
            hpPower: value('hp-power'),
            shiny: value('shiny'),
            ivs: Object.fromEntries(finder.STATS.map(stat => [stat, {
                min: value(`${stat}-min`), max: value(`${stat}-max`)
            }]))
        };
    }

    function markChanged() {
        if (results.length) status('Inputs changed. Run a new search to update the results below.');
    }

    byId('finder-fields').addEventListener('input', markChanged);
    byId('finder-fields').addEventListener('change', markChanged);

    document.querySelectorAll('.finder-reset').forEach(button => {
        button.addEventListener('click', () => {
            if (current) return; // Keep the search configuration fixed while it runs.
            const panel = button.closest('.finder-panel');
            // Read defaults from the HTML, and reset only this panel's controls.
            // The IV panel includes Hidden Power; trainer IDs sit outside both panels.
            panel.querySelectorAll('input').forEach(input => { input.value = input.defaultValue; });
            panel.querySelectorAll('select').forEach(select => {
                const defaultIndex = [...select.options].findIndex(option => option.defaultSelected);
                select.selectedIndex = defaultIndex === -1 ? 0 : defaultIndex;
            });
            const name = panel.querySelector('h2').textContent;
            status(`${name} reset to defaults.` + (results.length
                ? ' Run a new search to update the results below.'
                : ' Run a search to use these settings.'));
        });
    });

    byId('finder-copy-ids').addEventListener('click', () => {
        try {
            const tid = finder.decimal(byId('tid').value, 'Create save TID', 0, 65535);
            const sid = finder.decimal(byId('sid').value, 'Create save SID', 0, 65535);
            byId('finder-tid').value = tid;
            byId('finder-sid').value = sid;
            status('Copied both trainer IDs. Run a search to use this pair.');
        } catch (error) {
            status(`${error.message} Enter or randomize both IDs in Create save first.`, true);
        }
    });

    function renderPage() {
        const body = byId('finder-result-rows');
        const fragment = document.createDocumentFragment();
        const first = page * finder.PAGE_SIZE;
        for (const result of results.slice(first, first + finder.PAGE_SIZE)) {
            const row = byId('finder-result-row').content.firstElementChild.cloneNode(true);
            const values = [result.displayAdvance,
            result.pid.toString(16).toUpperCase().padStart(8, '0'), finder.NATURES[result.nature],
            ...finder.STATS.map(stat => `${result.ivs[stat]} (${result.stats[stat]})`),
            `${finder.HP_TYPES[result.hpType]} ${result.hpPower}`,
            result.shiny ? (result.shinyXor === 0 ? 'Square' : 'Star') : 'No'];
            [...row.cells].forEach((cell, index) => { cell.textContent = values[index]; });
            if (result.shiny) row.className = 'shiny-row';
            fragment.appendChild(row);
        }
        body.replaceChildren(fragment);
        const pages = Math.max(1, Math.ceil(results.length / finder.PAGE_SIZE));
        byId('finder-page').textContent = `Page ${page + 1} of ${pages} - ${results.length.toLocaleString('en-US')} matches`;
        byId('finder-previous').disabled = page === 0;
        byId('finder-next').disabled = page + 1 >= pages;
        document.querySelector('.table-scroll').scrollTop = 0;
    }

    byId('finder-previous').addEventListener('click', () => {
        if (page > 0) { page--; renderPage(); }
    });

    byId('finder-next').addEventListener('click', () => {
        if ((page + 1) * finder.PAGE_SIZE < results.length) { page++; renderPage(); }
    });

    function setRunning(running) {
        byId('finder-fields').disabled = running;
        byId('finder-search').disabled = running;
        byId('finder-cancel').disabled = !running;
        byId('finder-results').setAttribute('aria-busy', String(running));
    }

    function finish(job, cancelled = false) {
        if (job !== current) return;
        current = null;
        const restoreFocus = document.activeElement === byId('finder-cancel');
        setRunning(false);
        if (restoreFocus) byId('finder-search').focus();
        results = job.search.rows;
        page = 0;
        const { scanned, truncated, lastAdvance } = job.progress;
        const resultCount = `${results.length.toLocaleString('en-US')} matches in ${scanned.toLocaleString('en-US')} advances searched`;
        let message = cancelled ? `Search cancelled: ${resultCount}.` : `Search complete: ${resultCount}.`;
        if (truncated) message = `Stopped at the 5,000-match limit after advance ${lastAdvance}. Narrow the filters or continue with start advance ${lastAdvance + 1}.`;
        if (cancelled && scanned) message += ` Last searched advance: ${lastAdvance}.`;
        status(message);
        const config = job.config;
        const offsetIndicator = byId('finder-offset-indicator');
        closeHelp(offsetIndicator);
        offsetIndicator.hidden = config.offset === 0;
        offsetIndicator.setAttribute('aria-label', `About the applied display offset: ${config.offset}`);
        offsetIndicator.title = `Display offset: ${config.offset}. Advance = actual advance - (${config.offset}).`;
        byId('finder-result-offset-help').textContent =
            `Display offset: ${config.offset}. Advance = actual advance - (${config.offset}). ` +
            'Actual advance counts RNG calls before the PID. The offset is visual only.';
        byId('finder-result-summary').textContent =
            `TID: ${config.tid} - SID: ${config.sid} - Seed: ${config.seed.toString(16).toUpperCase().padStart(8, '0')} - ` +
            `Advance range: ${config.start}-${config.end} - Display offset: ${config.offset}. ${message}`;
        byId('finder-results').hidden = results.length === 0;
        renderPage();
    }

    function tick(job) {
        if (job !== current) return;
        try {
            job.progress = job.search.step();
            if (job.progress.done) { finish(job); return; }
            if (Date.now() - job.announced >= 500) {
                status(`Searching - ${job.progress.scanned.toLocaleString('en-US')} advances checked...`);
                job.announced = Date.now();
            }
            job.timer = setTimeout(() => tick(job), 0);
        } catch (error) {
            current = null;
            setRunning(false);
            status(`Search failed: ${error.message}`, true);
        }
    }

    byId('finder-cancel').addEventListener('click', () => {
        if (!current) return;
        clearTimeout(current.timer);
        finish(current, true);
        byId('finder-search').focus();
    });

    byId('finder-form').addEventListener('submit', event => {
        event.preventDefault();
        if (current) return;
        let config;
        try { config = finder.validateSearch(rawSearch()); }
        catch (error) { status(error.message, true); return; }
        results = [];
        byId('finder-result-rows').replaceChildren();
        byId('finder-results').hidden = true;
        const job = {
            config, search: finder.createSearch(config), announced: Date.now(),
            progress: { scanned: 0, lastAdvance: config.start - 1, truncated: false }
        };
        current = job;
        setRunning(true);
        status('Searching...');
        byId('finder-cancel').focus();
        job.timer = setTimeout(() => tick(job), 0);
    });
})();
